from collections import deque


class Solution:
    def shortestPathBinaryMatrix(self, grid: list[list[int]]) -> int:
        n = len(grid)
        if grid[0][0] or grid[n - 1][n - 1]:
            return -1                              # blocked start or end
        queue = deque([(0, 0)])
        grid[0][0] = 1                             # mark visited (reuses the grid)
        length = 1                                 # path length counts cells, start included
        while queue:
            for _ in range(len(queue)):            # one BFS level = one more cell on the path
                r, c = queue.popleft()
                if r == n - 1 and c == n - 1:
                    return length
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):          # 8 neighbours (0, 0 is the cell itself and is marked)
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == 0:
                            grid[nr][nc] = 1       # mark on enqueue: each cell queued once
                            queue.append((nr, nc))
            length += 1
        return -1

